-- 1. EXTENSIONS
CREATE EXTENSION IF NOT EXISTS "uuid-ossp";

-- 2. TABLE: settings
CREATE TABLE IF NOT EXISTS settings (
  id TEXT PRIMARY KEY,
  "dailyBookingCap" INTEGER DEFAULT 2,
  "bookingCancellationWindowHours" INTEGER DEFAULT 4,
  "defaultGstPercent" NUMERIC DEFAULT 18,
  "gracePeriodDays" INTEGER DEFAULT 7,
  "happyHourDiscountPct" NUMERIC DEFAULT 20,
  "happyHourStart" TEXT DEFAULT '17:00',
  "happyHourEnd" TEXT DEFAULT '20:00',
  "stripeEnabled" BOOLEAN DEFAULT true,
  "upiEnabled" BOOLEAN DEFAULT true,
  "walletAutoRefundEnabled" BOOLEAN DEFAULT true,
  "clubEmail" TEXT DEFAULT 'info@championsclub.in',
  "clubPhone" TEXT DEFAULT '+91 98765 43210'
);

-- 3. TABLE: invoices
CREATE TABLE IF NOT EXISTS invoices (
  id TEXT PRIMARY KEY,
  "invoiceNumber" TEXT UNIQUE NOT NULL,
  "memberId" TEXT,
  "recipientName" TEXT NOT NULL,
  "recipientEmail" TEXT,
  "recipientPhone" TEXT,
  "recipientGst" TEXT,
  category TEXT DEFAULT 'court_rental',
  items JSONB DEFAULT '[]'::jsonb,
  subtotal NUMERIC DEFAULT 0,
  "gstRate" NUMERIC DEFAULT 0.18,
  "gstAmount" NUMERIC DEFAULT 0,
  "totalAmount" NUMERIC DEFAULT 0,
  "paidAmount" NUMERIC DEFAULT 0,
  "balanceAmount" NUMERIC DEFAULT 0,
  "creditNoteAmount" NUMERIC DEFAULT 0,
  status TEXT DEFAULT 'unpaid',
  "dueDate" TEXT,
  "paidAt" TEXT,
  "paymentMethod" TEXT,
  "createdAt" TEXT,
  stream TEXT,
  reminders JSONB DEFAULT '[]'::jsonb
);

-- 4. TABLE: social_sessions
CREATE TABLE IF NOT EXISTS social_sessions (
  id TEXT PRIMARY KEY,
  title TEXT NOT NULL,
  sport TEXT NOT NULL,
  "courtIds" JSONB DEFAULT '[]'::jsonb,
  date TEXT NOT NULL,
  "startTime" TEXT NOT NULL,
  "endTime" TEXT NOT NULL,
  "maxParticipants" INTEGER DEFAULT 12,
  "currentParticipants" JSONB DEFAULT '[]'::jsonb,
  "participantDetails" JSONB DEFAULT '[]'::jsonb,
  waitlist JSONB DEFAULT '[]'::jsonb,
  organizer TEXT,
  level TEXT,
  fee JSONB
);

-- 5. TABLE: products (if not exists)
CREATE TABLE IF NOT EXISTS products (
  id TEXT PRIMARY KEY,
  name TEXT NOT NULL,
  sku TEXT UNIQUE NOT NULL,
  brand TEXT,
  category TEXT,
  price NUMERIC DEFAULT 0,
  "costPrice" NUMERIC DEFAULT 0,
  "stockQty" INTEGER DEFAULT 0,
  "reservedQty" INTEGER DEFAULT 0,
  "reorderLevel" INTEGER DEFAULT 5,
  "isServiceItem" BOOLEAN DEFAULT false,
  image TEXT
);

-- 6. TABLE: stock_movements
CREATE TABLE IF NOT EXISTS stock_movements (
  id TEXT PRIMARY KEY,
  "productId" TEXT,
  "productName" TEXT,
  change INTEGER NOT NULL,
  type TEXT,
  notes TEXT,
  "performedBy" TEXT,
  timestamp TEXT,
  "referenceId" TEXT
);

-- 7. TABLE: menu_items
CREATE TABLE IF NOT EXISTS menu_items (
  id TEXT PRIMARY KEY,
  name TEXT NOT NULL,
  description TEXT,
  price NUMERIC DEFAULT 0,
  "happyHourPrice" NUMERIC,
  category TEXT NOT NULL,
  station TEXT,
  "isAvailable" BOOLEAN DEFAULT true,
  image TEXT,
  tags JSONB DEFAULT '[]'::jsonb
);

-- 8. TABLE: tables
CREATE TABLE IF NOT EXISTS tables (
  id TEXT PRIMARY KEY,
  name TEXT NOT NULL,
  capacity INTEGER DEFAULT 4,
  status TEXT DEFAULT 'available',
  "activeTabId" TEXT,
  "assignedServerName" TEXT,
  "mergedWithTableIds" JSONB DEFAULT '[]'::jsonb
);

-- 9. TABLE: credit_notes
CREATE TABLE IF NOT EXISTS credit_notes (
  id TEXT PRIMARY KEY,
  "creditNoteNumber" TEXT UNIQUE NOT NULL,
  "invoiceId" TEXT REFERENCES invoices(id) ON DELETE SET NULL,
  "invoiceNumber" TEXT,
  "recipientName" TEXT,
  amount NUMERIC DEFAULT 0,
  reason TEXT,
  "issuedAt" TEXT,
  "issuedBy" TEXT
);

-- 10. TABLE: leads
CREATE TABLE IF NOT EXISTS leads (
  id TEXT PRIMARY KEY,
  "referenceNumber" TEXT UNIQUE NOT NULL,
  "fullName" TEXT NOT NULL,
  phone TEXT,
  email TEXT,
  "companyName" TEXT,
  interest TEXT,
  "sportInterest" JSONB DEFAULT '[]'::jsonb,
  "interestedTier" TEXT,
  source TEXT,
  status TEXT DEFAULT 'new',
  "assignedStaffName" TEXT,
  "estimatedValue" NUMERIC DEFAULT 0,
  notes TEXT,
  "followUpDate" TEXT,
  "createdAt" TEXT,
  "updatedAt" TEXT,
  "lostReason" TEXT,
  activities JSONB DEFAULT '[]'::jsonb,
  tasks JSONB DEFAULT '[]'::jsonb,
  "quoteIds" JSONB DEFAULT '[]'::jsonb,
  "convertedMemberId" TEXT
);

-- 11. TABLE: quotes
CREATE TABLE IF NOT EXISTS quotes (
  id TEXT PRIMARY KEY,
  "quoteNumber" TEXT UNIQUE NOT NULL,
  "leadId" TEXT REFERENCES leads(id) ON DELETE SET NULL,
  "clientName" TEXT NOT NULL,
  "clientEmail" TEXT,
  items JSONB DEFAULT '[]'::jsonb,
  subtotal NUMERIC DEFAULT 0,
  "gstAmount" NUMERIC DEFAULT 0,
  "totalAmount" NUMERIC DEFAULT 0,
  status TEXT DEFAULT 'draft',
  "validUntil" TEXT,
  "createdAt" TEXT,
  notes TEXT
);

-- 12. TABLE: business_clients
CREATE TABLE IF NOT EXISTS business_clients (
  id TEXT PRIMARY KEY,
  "companyName" TEXT NOT NULL,
  "clientCode" TEXT UNIQUE NOT NULL,
  "contactPerson" TEXT,
  email TEXT,
  phone TEXT,
  "gstNumber" TEXT,
  "panNumber" TEXT,
  address TEXT,
  "creditTerms" TEXT DEFAULT 'net_30',
  "contractValue" NUMERIC DEFAULT 0,
  "packageType" TEXT,
  "allocatedPasses" INTEGER DEFAULT 0,
  "passesUsed" INTEGER DEFAULT 0,
  status TEXT DEFAULT 'active',
  "leadId" TEXT REFERENCES leads(id) ON DELETE SET NULL,
  "createdAt" TEXT,
  notes TEXT
);

-- 13. TABLE: expenses
CREATE TABLE IF NOT EXISTS expenses (
  id TEXT PRIMARY KEY,
  "expenseNumber" TEXT UNIQUE NOT NULL,
  title TEXT NOT NULL,
  vendor TEXT,
  category TEXT NOT NULL,
  amount NUMERIC DEFAULT 0,
  "inputGstAmount" NUMERIC DEFAULT 0,
  "gstRate" NUMERIC DEFAULT 0,
  date TEXT NOT NULL,
  "dueDate" TEXT,
  status TEXT DEFAULT 'pending',
  "paidAt" TEXT,
  "paymentMethod" TEXT,
  "approvedBy" TEXT,
  notes TEXT
);

-- 14. TABLE: employees
CREATE TABLE IF NOT EXISTS employees (
  id TEXT PRIMARY KEY,
  "empId" TEXT UNIQUE,
  name TEXT NOT NULL,
  role TEXT NOT NULL,
  department TEXT NOT NULL,
  email TEXT,
  phone TEXT,
  status TEXT DEFAULT 'active',
  "salaryDetails" JSONB,
  "coachingProfile" JSONB,
  "bankAccount" TEXT,
  "leaveBalances" JSONB,
  "joinDate" TEXT,
  documents JSONB DEFAULT '[]'::jsonb
);

-- Add columns if employees table pre-existed
ALTER TABLE employees ADD COLUMN IF NOT EXISTS "empId" TEXT;
ALTER TABLE employees ADD COLUMN IF NOT EXISTS "salaryDetails" JSONB;
ALTER TABLE employees ADD COLUMN IF NOT EXISTS "coachingProfile" JSONB;
ALTER TABLE employees ADD COLUMN IF NOT EXISTS "bankAccount" TEXT;
ALTER TABLE employees ADD COLUMN IF NOT EXISTS "leaveBalances" JSONB;
ALTER TABLE employees ADD COLUMN IF NOT EXISTS "joinDate" TEXT;
ALTER TABLE employees ADD COLUMN IF NOT EXISTS documents JSONB DEFAULT '[]'::jsonb;

-- 15. TABLE: shifts
CREATE TABLE IF NOT EXISTS shifts (
  id TEXT PRIMARY KEY,
