-- 18. TABLE: leaves
CREATE TABLE IF NOT EXISTS leaves (
  id TEXT PRIMARY KEY,
  "employeeId" TEXT,
  "employeeName" TEXT,
  type TEXT NOT NULL,
  "startDate" TEXT NOT NULL,
  "endDate" TEXT NOT NULL,
  "daysCount" INTEGER NOT NULL,
  reason TEXT,
  status TEXT DEFAULT 'pending',
  "approvedBy" TEXT,
  "decisionComment" TEXT,
  "decidedAt" TEXT,
  "createdAt" TEXT
